const rows = $input.all().map(i => i.json);

// Gom nhom theo symbol + timeframe
const groups = {};
for (const r of rows) {
  const key = r.symbol + '|' + r.timeframe;
  if (!groups[key]) groups[key] = [];
  groups[key].push(r);
}

const tfLabel = { '1h': 'ngan han (1h, ~30 ngay)', '4h': 'trung han (4h, ~30 ngay)', '1d': 'dai han (1d, ~1 thang)' };
const symbolSet = new Set(rows.map(r => r.symbol));
const symbolList = Array.from(symbolSet);

const lastPrices = {};
const summaryBySymbol = {};

for (const symbol of symbolList) {
  const lines = [];
  for (const tf of ['1h', '4h', '1d']) {
    const arr = groups[symbol + '|' + tf];
    if (!arr || arr.length === 0) continue;
    const first = parseFloat(arr[0].close);
    const last = parseFloat(arr[arr.length - 1].close);
    const changePct = (((last - first) / first) * 100).toFixed(2);
    const high = Math.max(...arr.map(a => parseFloat(a.close)));
    const low = Math.min(...arr.map(a => parseFloat(a.close)));
    lines.push(`  - ${tfLabel[tf]}: tu ${first} den ${last} (${changePct}%), cao nhat ${high.toFixed(2)}, thap nhat ${low.toFixed(2)}`);
    lastPrices[symbol] = last;
  }
  summaryBySymbol[symbol] = lines.join('\n');
}

const dataText = symbolList.map(s => `${s}:\n${summaryBySymbol[s]}`).join('\n\n');

const prompt = `Ban la AI phan tich thi truong crypto, ket hop nhieu khung thoi gian de danh gia xu huong tong the.\nDu lieu:\n\n${dataText}\n\nTra loi DUY NHAT mot JSON array, khong them chu nao khac, dung format:\n[{"symbol": "BTCUSDT", "signal": "BUY|SELL|HOLD", "reason": "giai thich ngan gon dua tren ca 3 khung thoi gian"}]\n\nPhai co du 1 object cho moi symbol: ${symbolList.join(', ')}`;

return [{ json: { prompt, last_prices: lastPrices, symbol_list: symbolList } }];

const raw = $input.first().json;
const lastPrices = $('Build Multi-Timeframe Prompt').first().json.last_prices;
const symbolList = $('Build Multi-Timeframe Prompt').first().json.symbol_list;

let parsed;
try {
  parsed = JSON.parse(raw.response);
} catch (e) {
  parsed = [];
}

// Qwen doi khi tra object dang {"BTCUSDT": {...}} thay vi mang [...]
if (parsed && !Array.isArray(parsed) && typeof parsed === "object") {
  parsed = Object.values(parsed);
}

if (!Array.isArray(parsed) || parsed.length === 0) {
  parsed = symbolList.map(symbol => ({
    symbol,
    signal: "HOLD",
    reason: "parse_error: AI khong tra ve JSON hop le"
  }));
}

return parsed.map(p => ({
  json: {
    symbol: p.symbol,
    signal: (p.signal || "HOLD").toUpperCase(),
    reason: p.reason || "",
    price_at_signal: lastPrices[p.symbol] || null
  }
}));

const items = $input.all();
const hasError = items.some(i => i.json && i.json.error);
const meta = $('Set Workflow Meta').first().json;
return [{ json: {
  workflow_id: meta.workflow_id,
  version: meta.version,
  status: hasError ? 'partial_error' : 'success',
  started_at: meta.started_at,
  data: items.map(i => i.json)
}}];
